// План specs/addresses.md 3.1 / 3.2 (кейс AD-11). Pre-Prod, preprod-ttp (TTP Test Locks), EN. Лид не сохраняется. Зависит от Google Places.
import { test, expect } from '../../fixtures';
import { ROLE, addressInput, city, openNewLead, region, typeAndPickSuggestion, zip } from './lead-address-helpers';

test.describe('Адрес: City из подсказки — город, не район (#dad444)', () => {
  for (const device of ['@desktop', '@android'] as const) {
    test(`New Lead: "400 Broad St, Seattle" fills City = Seattle, not the neighborhood Uptown #dad444 ${device} @google-places`, async ({ asUser }) => {
      const page = await asUser(ROLE);
      await openNewLead(page);

      await typeAndPickSuggestion(page, '400 Broad St Seattle', '400 Broad St', 'Seattle, WA, USA');

      // ZIP приходит ~1 с после выбора — ждём значение.
      await expect(zip(page)).toHaveValue('98109');
      await expect(addressInput(page)).toHaveValue('400 Broad St, Seattle, WA 98109, USA');
      // источник: «מה רצוי» — בשדה City נכנסת העיר (Seattle), גם כשבכתובת יש שכונה
      await expect(city(page)).toHaveValue('Seattle');
      await expect(city(page)).not.toHaveValue('Uptown');
      await expect(region(page)).toHaveValue('Washington');
    });
  }
});
